#define assert(x) ((void)0)

class color
{
public:
  float r, g, b, a;
};

class element
{
protected:
  element *parent;
  char padding[28];
  float R[2][2];
  float T[2];
  float S[2];
  float S_Override[2];
  float O[2];
  float angle;
  color mycolor[4];
  char trailing[8];
public:
  virtual void transform(float v[2], color &c, int index);
};

void element::transform(float v[2], color &c, int index)
{
  assert(index < 4);
  float xt, yt;

  // scale them
  v[0] *= S[0] * S_Override[0];
  v[1] *= S[1] * S_Override[1];
  // rotate them
  xt = v[0] * R[0][0] + v[1] * R[0][1];
  yt = v[0] * R[1][0] + v[1] * R[1][1];
  v[0] = xt;
  v[1] = yt;
  // translate them
  v[0] += T[0];
  v[1] += T[1];
  if(parent)
  {
    parent->transform(v, c, index);
  }
  c.r *= mycolor[index].r;
  c.g *= mycolor[index].g;
  c.b *= mycolor[index].b;
  c.a *= mycolor[index].a;
}
